end

----从这个方法调进来  说明肯定是激活的技能
function OSManegeReportDescriptionCell:RefreshSkillDesShow(data)
    self:InitShow(true)
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local isCafeMax = component:IsToMaxCafeLevel()
    local skillId = isCafeMax and data.skill2 or data.skill1
    local recipeId = data.recipeId
    local type = data.recipeType
    ---@type MaidCoffeeConstants
    local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
    local iconPath = MaidCoffeeConstants.RecipeSkillTypeImg[type]
    CfUtils.FillImage(self.ImgFoodType,iconPath)
    local skillVo = MaidCoffeeUtils.GetMaidCoffeeRecipeSkillVo(skillId)
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local recipeDojo = component:GetRecipeDoJoById(recipeId)
    local addNum = string.split(skillVo.skillNum[recipeDojo.rating],",")
    local desc = MaidCoffeeUtils.FillCoffeeSkillDescription(skillVo.decr1, addNum,nil,skillVo.percentage)
    CfUtils.FillText(self.TextDesc,desc)
    CfUtils.SetUISwitchText(self.TextDesc,2)

    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(skillVo.rewardId)
    if goodsVo then
        CfUtils.FillImage(self.ActiveGoodsIcon,goodsVo.photoPath)
    end

end

function OSManegeReportDescriptionCell:RefreshPersonShow(id)
    if isNull(id) or checkNumber(id) <= 0 then return end
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardDojo = cardComponent:GetCardById(tonumber(id))
    ---设置心情值和状态 会刷新
    local point = tonumber(cardDojo.cafeEnergy) or 0
    self:RefreshBuffTxt(cardDojo.cardId)
    KTool.SetActive(self.NotActive.gameObject,point == 0)
    KTool.SetActive(self.Active.gameObject,point > 0)
    KTool.SetActive(self.FoodTypeMask.gameObject,false)
    local state = point > 0 and 2 or 1
    CfUtils.SetUISwitchText(self.TextDesc,state)
end

function OSManegeReportDescriptionCell:RefreshBuffTxt(staffId)
    local vo = MaidCoffeeUtils.GetCardManagerInfoVo(staffId)
    local skillVo = MaidCoffeeUtils.GetMaidCoffeeSkillInfoVo(vo.additionId)
    if skillVo then
        local skillDes = MaidCoffeeUtils.FillCoffeeSkillDescription(skillVo.decr,vo.additionNum,nil,vo.percentage) or ""
        ---因为店长有个特殊技能 会没有奖励ID 陈菲说这个技能只会出现在店长身上
        if checkNumber(skillVo.rewardId) > 0 then
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(skillVo.rewardId)
            if not isNull(goodsVo) then
                CfUtils.FillImage(self.ActiveGoodsIcon,goodsVo.photoPath)
                CfUtils.FillImage(self.NotActiveGoodsIcon,goodsVo.photoPath)
            end
        else
            CfUtils.FillImage(self.ActiveGoodsIcon,skillVo.icon)
            CfUtils.FillImage(self.NotActiveGoodsIcon,skillVo.icon)
        end

        CfUtils.FillText(self.TextDesc,skillDes)
    end
end

function OSManegeReportDescriptionCell:InitShow(state)
    KTool.SetActive(self.Active.gameObject,state)
    KTool.SetActive(self.NotActive.gameObject,not state)
    KTool.SetActive(self.FoodTypeMask.gameObject,state)

end

function OSManegeReportDescriptionCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OSManegeReportDescriptionCell